// Copies the compiled ShowUpV6 ABI into the web app so the frontend and API
// routes always use the ABI of the contract that is actually deployed.
//
// Usage: npm run compile && node scripts/sync-web-abi.mjs
// CI runs this and fails if web/src/lib/showup-abi.ts is out of date.
import { readFileSync, writeFileSync } from "node:fs";

const artifact = JSON.parse(
  readFileSync("artifacts/contracts/ShowUpV6.sol/ShowUpV6.json", "utf8"),
);

const source = `// Generated by scripts/sync-web-abi.mjs from the ShowUpV6 build artifact.
// Do not edit by hand: change the contract, compile, and run the script.

export const SHOWUP_ABI = ${JSON.stringify(artifact.abi, null, 2)} as const;
`;

writeFileSync("web/src/lib/showup-abi.ts", source);
console.log(`Wrote web/src/lib/showup-abi.ts (${artifact.abi.length} ABI entries)`);
